import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {World} from '../world.js';import {Battle,makeEnemy} from '../battle.js?v=5.6.0';import {defaultHero} from '../mako.js';import {applySupply} from '../repertoire.js?v=5.6.0';import {startOrigin,exitOrigin,FIELD_ORIGINS} from '../field-origins.js?v=5.6.0';import {APPROACHES,setApproach} from '../battle-approaches.js';import {findPath} from '../navigation.js';
const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));
test('all seven field origins preserve campaign state, timeline, kit and recruitment across save and exit',()=>{for(const o of FIELD_ORIGINS){const w=new World(data);w.state.timeline={id:'test-branch',era:'origin'};w.state.items.ether=7;const before=JSON.parse(w.save());w.state.mode='field';assert.ok(startOrigin(w,o.hero,'saboteur'));assert.equal(w.scene.fieldOrigin,o.hero);assert.deepEqual(w.state.party,[o.hero]);const monster=w.objects().find(x=>x.originHero===o.hero);assert.ok(monster);assert.ok(findPath(w.scene,[w.state.x,w.state.y],monster.xy,1).length);const resumed=new World(data);resumed.restore(w.save());assert.equal(resumed.scene.fieldOrigin,o.hero);resumed.state.mode='field';resumed.interact(monster);assert.equal(resumed.currentBattle.object.type,'origin');resumed.winBattle();assert.ok(resumed.state.fieldOrigins.completed.includes(o.hero));exitOrigin(resumed,false);assert.deepEqual(resumed.state.flags,before.flags);assert.deepEqual(resumed.state.timeline,before.timeline);assert.deepEqual(resumed.state.recruited,before.recruited);assert.deepEqual(resumed.state.items,before.items);assert.deepEqual(resumed.state.party,before.party);assert.equal(resumed.state.heroes[o.hero].battleApproach,'saboteur');assert.equal(resumed.state.xp,before.xp);assert.deepEqual(resumed.state.bosses,before.bosses);}});
function arena(role){const h={...defaultHero(0),battleApproach:role,x:1,y:1},e={...makeEnemy('predator',1),x:2,y:1};const b=new Battle({heroes:[h],enemies:[e]});h.atb=1;return {h,e,b};}
test('every approach is available to every companion and equipment is locked during battle',()=>{const w=new World(data);w.state.mode='field';for(const h of w.state.heroes)for(const a of APPROACHES)assert.ok(setApproach(w.state,h.id,a.id));w.state.mode='battle';assert.equal(setApproach(w.state,0,'courier'),false);});
test('supplies create six distinct bounded disciplines without bypassing inventory costs',()=>{let {h,e,b}=arena('weatherwright');assert.ok(applySupply(b,{tideFlask:1},'tideFlask',h,e));assert.equal(e.status.wet,9);
 ({h,e,b}=arena('saboteur'));assert.ok(applySupply(b,{shatterCharge:1},'shatterCharge',h,e));assert.equal(e.status.exposed,5);
 ({h,e,b}=arena('courier'));assert.ok(applySupply(b,{clockOil:1},'clockOil',h,e));assert.equal(h.atb,.25);
 ({h,e,b}=arena('reclaimer'));h.mp=0;const inv={tideFlask:1};assert.ok(applySupply(b,inv,'tideFlask',h,e));assert.equal(h.mp,4);assert.equal(inv.tideFlask,0);assert.equal(applySupply(b,inv,'tideFlask',h,e),false);
 ({h,e,b}=arena('witness'));h.status.burn=4;assert.ok(applySupply(b,{clearSalt:1},'clearSalt',h,e));assert.equal(e.status.exposed,5);
 ({h,e,b}=arena('glasskeeper'));h.status.shield=40;const old=e.hp;b.damage(e,h,50);assert.equal(e.hp,old-10);assert.ok(!b.events.some(x=>x.reaction==='glass-return'&&x.source===e));});
test('retreat and repeated origins cannot award campaign items, XP or guardian milestones',()=>{const w=new World(data);w.state.mode='field';const before=w.save();startOrigin(w,1,'witness');const object=w.objects().find(o=>o.originHero===1);w.interact(object);w.loseBattle();assert.deepEqual(w.state.fieldOrigins.completed,[]);exitOrigin(w,false);const base=JSON.parse(before);for(const key of ['items','xp','gold','bosses','flags'])assert.deepEqual(w.state[key],base[key]);});

test('borrowed origin kits cannot travel into the canonical campaign',()=>{const w=new World(data);w.state.mode='field';startOrigin(w,0,'weatherwright');const scene=w.state.scene;w.loadScene(5);assert.equal(w.state.scene,scene);exitOrigin(w,false);assert.equal(w.state.scene,2);});
test('an active past-era campaign survives field trials and resumes the same historical step',()=>{const w=new World(data);w.newGame({originId:'sable-reed'});w.state.mode='field';const before=JSON.parse(w.save());assert.equal(before.chronicle.phase,'past');startOrigin(w,4,'courier');assert.equal(w.state.chronicle,undefined);const resumed=new World(data);resumed.restore(w.save());exitOrigin(resumed,false);assert.deepEqual(resumed.state.chronicle,before.chronicle);assert.deepEqual(resumed.state.timeline,before.timeline);assert.equal(resumed.state.scene,before.scene);const final=new World(data);final.restore(resumed.save());assert.equal(final.state.chronicle.phase,'past');assert.equal(final.state.heroes[4].battleApproach,'courier');});
